class LRUCache {
    using Node = pair<int, int>; // {Key, Value}
    list<Node> dll;
    unordered_map<int, list<Node>::iterator> map;
    int capacity;

    void move_to_front(int key) {
        dll.splice(dll.begin(), dll, map[key]);
    }

public:
    LRUCache(int cap) : capacity(cap) {}

    int get(int key) {
        if (map.find(key) == map.end()) return -1;
        move_to_front(key);
        return map[key]->second;
    }

    void put(int key, int val) {
        if (map.count(key)) {
            map[key]->second = val;
            move_to_front(key);
        } else {
            dll.push_front({key, val});
            map[key] = dll.begin();
            if (map.size() > capacity) {
                map.erase(dll.back().first);
                dll.pop_back(); // Evict LRU node
            }
        }
    }
};
